from kit3 import *
from instruments import *
def cellp(name, svg, use): return f'<div style="width: 393px; flex: none; display: flex; flex-direction: column; gap: 8px;"><span style="{MONO} font-size: 11px; font-weight: 700; letter-spacing: 1.1px;">{name}</span><div style="width: 393px; background: {PAPER}; border-radius: 12px; padding: 18px 22px; box-sizing: border-box;">{svg}</div><div style="font-size: 12.5px; line-height: 17px; color: {MUTE};">{use}</div></div>'
cells = [cellp('the pier&rsquo;s day', pier_day(), 'One axis, 6 AM to 11 PM. The sun as a true half-sine between sunrise and sunset; the plan as gold on it; the film as ink on the line after dark. The water as a 12.42-hour harmonic with the high at 8:40; the low-water window on it; the kayaks under it.'),
         cellp('the evening', day_band(18, 23, [('19:15', '20:15', 'THE HOUR', 'gold')], [('20:45', 'DINNER 8:45', 'ring'), ('21:00', '', 'dot')], [('start', '6:45 DOORS', 'start'), ('end', 'LAST ORDERS 9 · CAFÉ TILL 11', 'end')]), 'The evening on one track from times, not pixels; a mark&rsquo;s label moves right, or to the end, when it would collide.'),
         cellp('two ways in', access_compare([('SUNSET PARK', [(3, 'foot'), (20, 'ride'), (9, 'foot')], 'THE N OR R · A LAND ROUTE, EASY TO SHORTEN'), ('RED HOOK', [(6, 'foot'), (25, 'ride'), (9, 'foot')], 'THE FERRY, EVERY 40 · A SCHEDULED WAY IN')]), 'Two access structures on one minutes scale: dots on foot, a bar for the ride, the total. The difference is drawn, not asserted.'),
         cellp('the flood section', section([(0, 0.6), (18, 0.6), (18, 1.2), (60, 1.2)], 0.9, [(2, 0.68, 'THE PIER · CREEK BED', 'start', INK), (20, 1.3, 'THE STREET · THE SILL, 1911', 'start', INK), (2, 0.96, 'HARBOR · HIGH WATER', 'start', WATER)], scale_m='m', h=118, zmax=1.42), 'Ground to scale: the pier on the creek bed, the 1911 sill 0.6 m above it, the harbor at high water between the two. The bar at the right says how tall the drawing is.'),
         cellp('the cliff section', section([(0, 40), (150, 40), (180, 36), (200, 0), (330, 0)], 0.3, [(4, 47, 'THE TOWN · THE READING ROOM', 'start', INK), (206, 7, 'THE QUAY · SEA LEVEL', 'start', INK), (172, 18, '40 M', 'end', GOLDD)], scale_m='m', h=118, zmax=54), 'The same renderer, Sorrento: 180 metres on the map, forty metres down.')]
h = HEAD + BOARD_OPEN.replace('min-height: 5233px', 'min-height: 900px') + headblock('INSTRUMENTS · TEST', 'Instruments from data', '') + '<div style="display: flex; gap: 46px; flex-wrap: wrap; align-items: flex-start;">' + ''.join(cells) + '</div>' + FOOT + TAIL
open('out2/_instr.html', 'w').write(h); print('ok')
